    seg[node] = (p[li] >= p[ri]) ? li : ri;
}

// Query for index of maximum in [ql, qr]
int query(int node, int l, int r, int ql, int qr){
    if(qr < l || r < ql) return -1; // invalid
    if(ql <= l && r <= qr) return seg[node];
    int mid = (l + r) >> 1;
    int leftIdx = query(node<<1, l, mid, ql, qr);
    int rightIdx = query(node<<1|1, mid+1, r, ql, qr);
    if(leftIdx == -1) return rightIdx;
    if(rightIdx == -1) return leftIdx;
    return (p[leftIdx] >= p[rightIdx]) ? leftIdx : rightIdx;
